const envelope = $json.body ?? $json;
const workspaceRecordId = String(envelope.workspaceRecordId ?? envelope.recordId ?? $json.query?.workspaceRecordId ?? '').trim();
if (!/^rec[a-zA-Z0-9]{14}$/.test(workspaceRecordId)) {
  throw new Error('Missing valid Workspace IDs record ID. Send {"workspaceRecordId":"rec..."}.');
}
return [{json:{workspaceRecordId,requestedAt:new Date().toISOString()}}];

const request = $('Validate Provision Request').first().json;
const workspaceResponse = $('Get Provision Workspace').first().json;
if (!workspaceResponse?.fields) throw new Error('Workspace record could not be loaded.');
const workspace = workspaceResponse.fields;
const onboarding = $('Get Provision Onboarding').first().json?.fields || {};
const existing = ($('Find Existing Agent Settings').first().json.records || [])[0];
const current = existing?.fields || {};
const pick = (object,names) => names.map(name=>object?.[name]).find(value=>value!==undefined&&value!==null&&String(value).trim()) || '';
const workspaceName = String(workspace.Name || pick(onboarding,['Company Name','What is the name of your company?']) || request.workspaceRecordId);
const calendarLink = String(current['Calendar Link'] || pick(onboarding,['Calendar Link','What is your calendar link?','Booking Link']) || '');
const timezone = String(current.Timezone || pick(onboarding,['Timezone','Time Zone']) || 'America/New_York');
const fields = {
  ...current,
  'Workspace Key':String(current['Workspace Key'] || workspace['Workspace ID'] || workspace['EmailBison Workspace ID'] || request.workspaceRecordId),
  'Workspace Name':workspaceName,
  'Workspace Record ID':request.workspaceRecordId,
  'Enabled':current.Enabled === true,
  'Default Mode':String(current['Default Mode'] || 'Approval Required'),
  'Reply Handoff Mode':String(current['Reply Handoff Mode'] || 'Disabled'),
  'OOO Mode':String(current['OOO Mode'] || 'Approval Required'),
  'Not Interested Nudge':current['Not Interested Nudge'] === true,
  'Minimum Auto Confidence':Number(current['Minimum Auto Confidence'] ?? 0.9),
  'Max Automatic Replies':Number(current['Max Automatic Replies'] ?? 0),
  'Response Tone':String(current['Response Tone'] || 'Warm'),
  'Response Length':String(current['Response Length'] || 'Brief'),
  'Timezone':timezone,
  'Office Start':String(current['Office Start'] || '09:00'),
  'Office End':String(current['Office End'] || '17:00'),
  'Exclude Weekends':current['Exclude Weekends'] !== false,
  'Exclude US Holidays':current['Exclude US Holidays'] !== false,
  'Calendar Link':calendarLink || undefined,
  'Follow-up Instructions':String(current['Follow-up Instructions'] || ''),
  'Company Context Override':String(current['Company Context Override'] || ''),
  'Last Updated':new Date().toISOString()
};
for (const key of Object.keys(fields)) if (fields[key] === undefined) delete fields[key];
const settingsBody = {performUpsert:{fieldsToMergeOn:['Workspace Record ID']},records:[{fields}],typecast:true};
const intakeUrl='https://n8n.dulcy.io/webhook/REDACTED_PATH?workspaceRecordId='+request.workspaceRecordId;
return [{json:{...request,workspace,onboarding,existingSettingsId:existing?.id||'',settingsBody,intakeUrl,webhookName:'Dulcy Reply Agent - '+workspaceName}}];

if($json.error||$json.success===false||$json.data?.success===false)throw new Error('Webhook lookup failed; registration stopped.');

const provision=$('Prepare Client Provisioning').first().json;
const response=$json?.data ?? $json;
const rows=Array.isArray(response)?response:(Array.isArray(response?.data)?response.data:(Array.isArray(response?.webhooks)?response.webhooks:[]));
const existing=rows.find(row=>String(row?.url||row?.webhook_url||'')===provision.intakeUrl);
return [{json:{...provision,webhookExists:Boolean(existing),existingWebhook:existing||null}}];
